(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-dual-stream-full-duplex"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-1\">一 · 一次长会话中的显存塌陷：为什么级联架构之外还需要别的答案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-2\">二 · 它究竟解决哪一个推理问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-3\">三 · 它不解决什么：三条清晰的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-4\">四 · 与相邻方案的取舍点在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-5\">五 · 事故复现路径与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-6\">六 · 全双工不是“把两路音频拼在一起”：边界、失效面与代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-7\">七 · 用户流编码：帧块入队与双 token 产出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-8\">八 · 双流交错输入：文本 token 作为内部桥梁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-9\">九 · 助手流自回归与用户流并发更新</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-10\">十 · 声码器流式解码与文本字幕同步输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-11\">十一 · 打断检测：助手流清空与 KV 重置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-12\">十二 · 端到端时延分解与调度约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-13\">十三 · 双流交错下的失效边界与代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-14\">十四 · 交错注意力的张量形状与掩码推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-15\">十五 · 轮次延迟公式的逐项分解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-16\">十六 · KV 按流分区的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-17\">十七 · 打断检测与 KV 重置的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-18\">十八 · 文本桥接的注意力约束与可控生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-19\">十九 · 交错注意力的边界：KV 分区、打断重置与重叠语音的失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-20\">二十 · 什么样的请求形态才喂得饱双流引擎</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-21\">二十一 · 长度分布：用户流是长尾，助手流是短块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-22\">二十二 · 并发与批大小：被双流 KV 显存钉死的上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-23\">二十三 · 负载不对时的三种典型塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-24\">二十四 · 配方表的工程读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-25\">二十五 · 双流全双工的负载配方：什么请求形态吃得下，什么形态会把它压垮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-26\">二十六 · 硬件档位的选取逻辑：从 SM 与显存带宽反推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-27\">二十七 · 并行拓扑：编码、LM、声码器三段流水</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-28\">二十八 · 量化方案：FP16 主干与按流分区的 KV 精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-29\">二十九 · KV 策略：分区、滑窗与打断重置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-30\">三十 · 调度参数：批大小、队列深度与打断阈值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-31\">三十一 · 可复现的配置思路：从约束到参数的推导链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-32\">三十二 · 双流 KV 的显存账：谁在挤占谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-33\">三十三 · 带宽：交错注意力的读放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-34\">三十四 · 通信：打断重置的同步代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-35\">三十五 · 功耗与 SM 占用：双流并行的常驻成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-36\">三十六 · 尾延迟：规模上去后先崩的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-37\">三十七 · 容量规划的落点：按流分账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-38\">三十八 · 双流 KV 的显存墙与规模崩塌点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-39\">三十九 · 精度漂移：从 FP16 到低比特的静默失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-40\">四十 · OOM 的真实来源：用户流挤占助手流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-41\">四十一 · 批抖动与路由不均</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-42\">四十二 · 尾延迟尖刺：打断滞后与声码器流水断流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-43\">四十三 · 监控分层与回滚策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-44\">四十四 · 工程判断：把失败模式绑到流分区上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-45\">四十五 · 双流全双工推理的失效边界：显存挤占、打断错位与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-46\">四十六 · 对照轴：三条正交维度而非一条“先进度”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-47\">四十七 · 并行度轴：端到端往返次数与 KV 复杂度的交换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-48\">四十八 · 对齐载体轴：内部文本 token 与外部文本接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-49\">四十九 · 状态可重置性轴：打断语义决定调度形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-50\">五十 · 决策表落地：按 SLO 与预算反推，而非按模型名气</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-dual-stream-full-duplex-sec-51\">五十一 · 边界判定：三族语音对话推理的选型分水岭</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:534px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 534.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用户音频按帧块流入编码器，得到语义 token 与声学 token</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">多流 Transformer 将用户流与助手流交错输入，文本 token …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">助手流自回归生成音频 token，同时用户流持续更新以支持打断</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">助手音频 token 流式送声码器解码播放，文本 token 可同步输出字幕</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"452.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">打断检测触发助手流清空与 KV 重置，保留用户流状态继续监听</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-dual-stream-full-duplex-sec-1\">一 · 一次长会话中的显存塌陷：为什么级联架构之外还需要别的答案</h3>\n<p>把时间拨回到一次典型的线上故障复盘：某语音助手在灰度环境中接入了长会话场景，单次通话时长从平均四十多秒拉长到数分钟。监控最先报警的不是错误率，而是 P99 首包延迟——它没有陡增，而是缓慢爬升，随后在一批会话中直接触发 OOM 重启。根因并不复杂：级联架构下 ASR、LLM、TTS 三段各自持有独立的会话状态，ASR 侧按固定窗口滑窗、LLM 侧按轮次重建上下文、TTS 侧按句切分，三段之间靠文本边界同步。当用户说话不停顿、助手又在播放上一轮回应时，三段的状态机开始互相等待，队列积压把端到端延迟推高，而为了兜住延迟而扩大的批又把显存吃满。这个事故暴露的不是某个模块的 bug，而是级联范式本身的结构性缺陷：它把一次本应并行的双向交互，强行拆成了串行的三段往返。</p>\n<p>级联架构的延迟账可以写得很直白。设一轮交互中编码耗时为 $t_{\\text{enc}}(B_u)$、语言模型耗时为 $t_{\\text{lm}}(B_a)$、声码器耗时为 $t_{\\text{voc}}(B_a)$，则一轮的串行下限为</p>\n<div class=\"formula\">$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a),\\quad \\text{streams}=2$$</div>\n<p>这个式子里没有任何一项能与其他项重叠，因为文本边界是硬同步点：ASR 不给出完整句，LLM 无法起跑；LLM 不吐出足够长的文本块，TTS 无法开声。更关键的是，它天然不支持“用户还在说、助手已经开始回应”这种人类对话中极常见的重叠。事故中的延迟爬升，本质上是三段流水线在等待彼此，而批大小 $B_u$、$B_a$ 一旦为了摊薄单次开销而调大，首包延迟与显存占用就同时恶化。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-2\">二 · 它究竟解决哪一个推理问题</h3>\n<p>双流全双工要解决的具体问题只有一个：把“听”和“说”从串行两段变成同一模型内并行的两条流，从而消掉级联的多次往返，并让打断成为一等公民。机制上，用户音频按帧块流入编码器，得到语义 token 与声学 token；单一多流 Transformer 把用户流与助手流交错输入，文本 token 作为内部桥梁；助手流自回归生成音频 token，与此同时用户流持续更新。助手音频 token 流式送声码器解码播放，文本 token 可同步输出字幕。打断检测一旦触发，助手流清空并重置其 KV，而用户流状态保留、继续监听。</p>\n<p>这里的核心不是“把三个模型塞进一个”，而是注意力层面的交错。助手流第 $t$ 步的隐状态由下式给出：</p>\n<div class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</div>\n<p>其中上标 user/asst/text 分别对应用户音频流、助手音频流与内部文本 token 的 KV，$\\oplus$ 表示按交错顺序拼接。交错顺序直接决定听与说的并行程度：把用户流的最新块排在助手流当前块之前，助手每一步都能看到用户“刚刚”说了什么；把文本 KV 夹在中间，则语音与文本语义被强制对齐，字幕与发声不会各说各话。这个设计带来的推理代价是实打实的——KV cache 不再是单条线性增长的序列，而是三条来源不同、增长速率不同的分区，注意力模式从规则的下三角掩码变成按流交错的分段掩码，显存与带宽开销显著高于单向流式 TTS。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-3\">三 · 它不解决什么：三条清晰的边界</h3>\n<p>第一条边界是并发规模。双流交错使 KV 按流分区管理成为必须，而用户流在长会话中持续增长，会不断挤占助手流可用的显存。批大小因此不再由算力决定，而由双流 KV 的显存上限决定；并发会话数同时受 SM 占用与显存限制。这不是调参能绕过的，它是算法形态自带的天花板。</p>\n<p>第二条边界是鲁棒性的数据依赖。全双工训练数据稀缺，重叠语音与打断场景的样本不足时，打断检测会误触发或漏触发：阈值偏松，助手在用户只是换气时就被清空；阈值偏紧，用户明确打断后助手仍在输出旧回应，交互出现明显错位。算法本身不提供“无数据也能鲁棒”的保证，它把这个问题显式地交给了数据增强。</p>\n<p>第三条边界是任务形态。它面向的是低延迟、可打断的实时语音对话；对离线转写、长文档朗读、单向播报这类没有并行输入需求的场景，双流带来的 KV 复杂度与显存开销是纯负担，级联或单向流式反而是更合适的工程选择。换句话说，它不是“更快的 TTS”，也不是“带语音的 LLM”，它的适用域被“用户流必须持续在场”这一条严格限定。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-4\">四 · 与相邻方案的取舍点在哪里</h3>\n<p>相对级联 ASR/LLM/TTS，它的收益是消除多次往返并原生支持打断，代价是把三段各自成熟的工程优化（ASR 的滑窗、LLM 的连续批处理、TTS 的分块合成）压缩进一个模型的注意力模式里，任何一段的调度策略都要重新设计。相对单向流式 TTS，它增加了用户流并行输入与内部文本对齐，换来的是可打断性，付出的是 KV 与注意力模式的复杂度与更高的显存开销。这两条对比决定了选型判断：当产品指标里“打断响应时间”与“端到端响应延迟”同时是硬 SLO 时，双流是唯一能同时满足的形态；当其中一项可以放宽，级联或单向流式的工程风险明显更低。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>级联 ASR/LLM/TTS</th><th>单向流式 TTS</th><th>双流全双工</th></tr></thead><tbody><tr><td>往返次数</td><td>三段串行，多次同步</td><td>两段，文本到语音</td><td>单模型内并行，无硬同步点</td></tr><tr><td>打断支持</td><td>需外部状态机协调</td><td>不支持并行输入</td><td>原生，重置助手 KV 保留用户流</td></tr><tr><td>KV 形态</td><td>各段独立</td><td>单条序列</td><td>按流分区、交错注意力</td></tr><tr><td>显存压力</td><td>分散但可分别裁剪</td><td>较低</td><td>高，受双流 KV 约束</td></tr></tbody></table>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-5\">五 · 事故复现路径与工程判断</h3>\n<p>把第一节的事故放到双流形态下重演，会看到另一类失败：若 KV 未按流分区管理，用户流在长会话中持续增长，助手流的可用显存被逐步侵蚀，表现为响应延迟随会话时长单调上升，最终显存溢出。若打断检测阈值设置不当，助手流清空与 KV 重置滞后，用户打断后仍输出旧回应，交互错位比级联更刺眼，因为用户能同时听到自己的声音和助手的旧话音。这两条失败模式都指向同一个工程判断：双流全双工的稳定性不取决于模型本身，而取决于 KV 分区管理与打断状态机的实现质量。</p>\n<p>因此适用边界的表述应当是定性的而非乐观的：它适合低延迟全双工语音对话与可打断交互，上限由双流 KV 显存与带宽约束、并发会话数由 SM 与显存共同限制；重叠语音与打断的鲁棒性依赖专门数据增强，数据稀缺时性能下降。部署侧的现实约束同样明确——量化以 FP16 为主，KV 需按流分区管理，用户流编码与助手流解码并行、声码器流式解码与 LM 解码流水，调度必须同时维持两条流的推进节奏。任何把这些约束当成“后续优化项”的容量规划，都会在长会话与高并发叠加时重演第一节的显存塌陷。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-6\">六 · 全双工不是“把两路音频拼在一起”：边界、失效面与代价账</h3>\n<p>先看一个线上事故形态：某语音助手在级联架构下，ASR 必须等到用户停顿（端点检测）才出最终文本，LLM 再整段生成，TTS 再合成——用户说到一半改口“不是这个，我是说……”，系统仍把前半句的回应播完，打断要等播放结束才生效。把这条链路换成双流全双工后，事故并没有自动消失，而是换了个位置爆发：双流交错 KV 未按流分区管理，用户流持续增长挤占助手流显存，长会话下显存溢出或响应延迟上升；打断检测阈值设置不当，助手流清空与 KV 重置滞后，用户打断后仍输出旧回应，交互出现明显错位。这两类失败恰好划出了本方案的适用边界——它解决的是级联架构的多次往返与“不能边说边听”，不解决声学前端质量、不解决语义正确性、也不解决数据稀缺下的重叠语音判别。</p>\n<p>边界的第一层是“它替换了什么”。级联架构的延迟账是串行三段：$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a),\\quad \\text{streams}=2$$，其中 $B_u$、$B_a$ 分别是用户音频块与助手音频块的批大小。双流方案把三段压进一个多流 Transformer 的单次前向：用户音频按帧块流入编码器得到语义 token 与声学 token，多流 Transformer 将用户流与助手流交错输入，文本 token 作为内部桥梁，助手流自回归生成音频 token 的同时用户流持续更新。核心交错注意力为 $$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$，交错顺序直接决定听与说的并行程度。代价是注意力模式从单向因果变成三源拼接，KV 布局必须按流分区，否则用户流的持续增长会线性侵蚀助手流的可用显存——这是显存与带宽开销高的结构性来源，而非实现瑕疵。</p>\n<p>第二层边界是“它不保证什么”。文本 token 作为内部对齐桥梁，保证的是语音与文本语义一致、便于可控生成与同步字幕，但它不保证打断判定的正确性：全双工训练数据中重叠语音样本不足时，真实重叠语音下助手流会误触发或漏触发，对话轮次混乱。也就是说，鲁棒性依赖专门的数据增强，数据稀缺时性能下降，这不是调参能补的。部署上还有硬上限：并发会话数受 SM 与显存限制，批大小受双流 KV 显存约束，量化以 FP16 为主，声码器流式解码与 LM 解码需做流水才能不让 vocoder 成为尾延迟瓶颈。下表把“解决/不解决”对齐到可观测指标：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>本方案覆盖</th><th>不覆盖或需外部兜底</th><th>观测指标</th></tr></thead><tbody><tr><td>往返延迟</td><td>消除 ASR/LLM/TTS 多次往返</td><td>编码器前端与网络抖动</td><td>端到端响应延迟</td></tr><tr><td>打断</td><td>助手流清空 + KV 重置，保留用户流状态</td><td>阈值判定与重叠语音判别</td><td>打断响应时间、误触发率</td></tr><tr><td>显存</td><td>按流分区管理 KV</td><td>长会话用户流增长</td><td>KV 占用、溢出次数</td></tr><tr><td>语义一致</td><td>文本 token 内部对齐</td><td>事实正确性与策略约束</td><td>字幕/语音一致性抽检</td></tr></tbody></table>\n<p>工程判断落在调度器上：调度需同时维持用户流编码与助手流解码，打断时只重置助手 KV、保留用户流状态继续监听——这条“部分重置”语义若实现成全量重建，打断响应时间会被编码器重跑拖长，等于把全双工的卖点退化成级联。适用边界因此很具体：适合低延迟、可打断的全双工语音对话；不适合以长文档语义推理为主、语音只是输入通道的场景，也不适合重叠语音数据尚未增强就上线的场景。上限由双流 KV 显存与带宽约束决定，扩容先看每会话 KV 分区预算，再看 SM 占用，而不是先加批大小。</p>\n<h3 id=\"alg-dual-stream-full-duplex-sec-7\">七 · 用户流编码：帧块入队与双 token 产出</h3>\n<p>全双工推理的第一个可观测动作不是解码，而是用户流的帧块入队。音频前端以固定帧块（chunk）为单位把 PCM 送进流式编码器，编码器输出两路 token：语义 token 供多流 Transformer 做语义层面的对齐，声学 token 供后续与助手流做声学层面的耦合。这一步的输入是长度为 <em>c</em> 的帧块及其携带的会话标识；输出是语义 token 序列与声学 token 序列，二者共享同一时间轴但码本不同。代价集中在编码器的前向计算与激活带宽：帧块越小，单次前向的算力占用越低、但单位音频的重复上下文计算越多；帧块越大，编码器吞吐上升而首 token 可见延迟上升。工程上把这一步放在独立的 CUDA 流上，与助手流解码形成流水，使编码器前向不占用解码 kernel 的 SM 时间片。具体例子：会话建立后用户持续说话，编码器每收到一个帧块即产出一组 token 并追加到用户流 KV 的尾部，追加动作本身只写 KV、不触发注意力重算，因此用户流的状态增长是单调的、与助手流是否在解码无关。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-8\">八 · 双流交错输入：文本 token 作为内部桥梁</h3>\n<p>交错输入是本机制的核心步骤，也是全部代价的来源。多流 Transformer 在每一步把三路 KV 拼接后做注意力，助手流第 <em>t</em> 步的隐状态为：</p>\n<div class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</div>\n<p>输入是助手流当前的 query、用户流已累积的 KV、助手流自身已生成的 KV，以及内部文本 token 的 KV；输出是助手流当前步的隐状态，用于下一步的音频 token 采样。交错顺序决定听与说的并行程度：把用户流 KV 放在拼接段前部，助手流每步都要对持续增长的用户 KV 做注意力，这是显存与带宽开销的直接来源；把文本 KV 置于中段，则文本 token 同时被两路音频流读取，充当语义一致的锚点。代价可以按注意力 FLOPs 与 KV 读取字节数估算：设用户流长度为 <em>L<sub>u</sub></em>、助手流长度为 <em>L<sub>a</sub></em>、文本长度为 <em>L<sub>t</sub></em>，单步注意力的 KV 读取量正比于 <em>L<sub>u</sub>+L<sub>a</sub>+L<sub>t</sub></em>，而 <em>L<sub>u</sub></em> 随会话时长单调增长，因此长会话下每步解码的带宽成本是上升的，而不是常数。具体例子：一轮对话进行到数十秒时，用户流 KV 已远长于助手流 KV，助手流每生成一个音频 token 都要扫过整段用户 KV，此时解码从算力受限转为带宽受限，KV 分区管理成为决定吞吐的环节。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-9\">九 · 助手流自回归与用户流并发更新</h3>\n<p>助手流按音频 token 逐块自回归生成，同时用户流持续追加新帧块的 KV。两条流的更新节奏不同：助手流是解码步驱动，用户流是音频时钟驱动，二者在同一注意力核内被拼接读取，因此调度器必须保证用户流追加不会与助手流解码发生 KV 写冲突。输入是上一步采样出的音频 token 与用户流新入队的 token；输出是新的助手流 KV 与更新后的用户流 KV。代价体现在两个方向：助手流解码的每步延迟受批内其他会话的用户流长度牵制，批大小受双流 KV 显存约束；用户流的持续追加使显存占用随时间线性上升，若不按流分区管理，用户流会挤占助手流的可用显存。工程做法是把用户流 KV 与助手流 KV 放在不同的显存池，并为用户流设置按会话的配额，超出配额的旧帧块做滑动窗口截断而非无限增长。具体例子：批内同时存在长会话与短会话时，长会话的用户流 KV 拉高了整个批的注意力读取量，短会话的解码步被拖慢；按流分区并对用户流做窗口截断后，批内各会话的解码步延迟趋于一致。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-10\">十 · 声码器流式解码与文本字幕同步输出</h3>\n<p>助手音频 token 以块为单位送入声码器做流式合成，文本 token 同步解码为字幕。输入是助手流刚产出的音频 token 块与对应的文本 token；输出是波形块与字幕文本。这一步的代价是流水线耦合：声码器合成一个块的时间必须小于等于 LM 产出下一个块的时间，否则声码器成为端到端延迟的瓶颈；文本解码与音频解码共享同一批隐状态，若文本头与音频头在同一前向中并行计算，则文本字幕的可见延迟与音频首块延迟接近，若串行则字幕滞后。工程上把声码器放在独立流上，与 LM 解码形成生产者—消费者流水，音频 token 块一产出即入队声码器，LM 不等声码器返回就继续下一步。具体例子：助手流生成第一块音频 token 后立即触发声码器合成，用户在音频首块播放前就能看到字幕首句，字幕与语音的时间对齐由文本 token 与音频 token 的同步产出保证，而不是事后强制对齐。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-11\">十一 · 打断检测：助手流清空与 KV 重置</h3>\n<p>打断检测是全双工推理中最容易出错的步骤。检测器读取用户流的语义 token 与声学特征，判定用户是否在助手说话期间开始发言；一旦触发，执行三个动作：清空助手流已生成的 token 队列、重置助手流 KV、保留用户流 KV 继续监听。输入是用户流的最新 token 与当前助手流的播放进度；输出是重置后的助手流状态与继续增长的用户流状态。代价是重置的时机成本：重置滞后会让助手继续输出旧回应，交互错位；重置过早会误截断正常轮次。重置本身是一次 KV 区域的批量释放与重新分配，若 KV 按流分区管理，释放只作用于助手流池，用户流池不受影响，因此重置的显存代价可控；若两流共享同一 KV 池，重置需要重建索引，代价随会话长度上升。具体例子：用户在助手播报中途插话，检测器在用户流出现新的语义 token 后触发重置，助手流 KV 被清空、播放队列被丢弃，用户流 KV 原样保留，下一轮助手流从保留的用户流上下文重新起解码，避免把被打断的旧回应带入新轮次。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-12\">十二 · 端到端时延分解与调度约束</h3>\n<p>把上述步骤串起来，一轮的端到端时延可分解为编码、LM 解码与声码器三段：</p>\n<div class=\"formula\">$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a),\\quad \\text{streams}=2$$</div>\n<p>其中 <em>B<sub>u</sub></em> 是用户帧块大小、<em>B<sub>a</sub></em> 是助手音频 token 块大小，两路流并行意味着 <em>t<sub>enc</sub></em> 与 <em>t<sub>lm</sub></em> 在时间上重叠而非串行相加，公式给出的是单轮关键路径的上界。调度约束由此明确：批大小受双流 KV 显存约束，SLO 以端到端响应延迟与打断响应时间两项衡量，调度器必须同时维持用户流编码与助手流解码两条活跃路径。代价判断落在显存与带宽上：双流交错使注意力模式复杂，KV 读取量随用户流长度增长，长会话下带宽而非算力成为瓶颈；并发会话数受 SM 与显存限制，用户流配额与助手流池的划分直接决定可承载的会话规模。具体例子：容量规划时先按目标会话时长估算用户流 KV 的稳态占用，再按助手流块大小估算解码侧的 KV 与激活峰值，两者相加得到单会话显存基线，除以 GPU 可用显存得到并发上限；若用户流不做窗口截断，稳态占用随会话时长无界增长，并发上限随时间衰减，这正是双流 KV 未分区管理时的典型失败模式。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-13\">十三 · 双流交错下的失效边界与代价结构</h3>\n<p>把机制步骤按数据流顺序摊开后，真正决定这套方案能否落地的不是“能并行听与说”，而是三处耦合点的边界：用户流 KV 的无界增长、打断检测的判定滞后、以及交错注意力本身带来的带宽放大。设第 $i$ 个会话在时刻 $t$ 的用户流 KV 长度为 $n_u(t)$、助手流为 $n_a(t)$、文本桥接为 $n_x(t)$，则单会话 KV 占用为 $M_{\\text{kv}}=b\\cdot L\\cdot\\big(n_u+n_a+n_x\\big)\\cdot d_h$（$b$ 为每元素字节数，$L$ 为层数，$d_h$ 为头维），而用户流在整段会话内单调不减——这是与单向流式 TTS 最本质的差别：后者的 KV 随输出结束而封顶，前者的用户流只要麦克风开着就在长。工程上必须给 $n_u$ 设滑动窗口上限并对窗口外做摘要压缩，否则长会话下用户流会挤占助手流预留的显存块，表现为助手流解码块延迟抬升而非直接 OOM，这种“慢性退化”比崩溃更难定位。</p>\n<p>交错注意力的代价不在 FLOPs 而在 KV 读取带宽。助手流第 $t$ 步需拼接三路 KV：</p>\n<div class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</div>\n<p>拼接顺序即并行程度：若把用户流块排在助手流块之前，助手每步都要重读整段用户 KV，读取量随 $n_u$ 线性上升；若按块交错并复用上一步已读入的 K/V 分片，可把增量读取压到仅新增帧块。代价是分片驻留需要按流分区管理 KV——用户流、助手流、文本桥接各自独立的页表与回收策略，任何一路的分配器抖动都会传导到另两路的解码节拍。以 FP16 为主的量化档位下，KV 分区管理带来的显存碎片与跨流拼接的额外拷贝，是这套方案相对级联架构最直接的吞吐税。</p>\n<p>打断路径是第二个失效面。检测触发后需清空助手流 KV 并重置其位置编码，同时保留用户流状态继续监听；若阈值偏保守，重置滞后，用户已开口而助手仍在吐旧回应，交错注意力会把旧助手 KV 当作上下文继续参与，错位被放大而非自愈。反之阈值偏激进，助手流被频繁清空，轮次碎片化。可用的判据是把打断响应时间纳入 SLO，与端到端响应延迟并列考核：前者约束检测到重置的步数上限，后者约束 $t_{\\text{enc}}(B_u)+t_{\\text{lm}}(B_a)+t_{\\text{voc}}(B_a)$ 的预算分配。声码器流式解码与 LM 解码流水化后，$t_{\\text{voc}}$ 可被隐藏，但重置发生时流水线中已排队的音频块必须丢弃，这段丢弃窗口就是可感知的错位时长。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>用户流 KV 无窗口上限</td><td>长会话 $n_u$ 单调增长，挤占助手流预留块</td><td>助手解码块延迟抬升、显存碎片化</td></tr><tr><td>打断阈值滞后</td><td>重置前旧助手 KV 仍参与交错注意力</td><td>打断响应时间超 SLO、输出错位</td></tr><tr><td>重叠语音样本不足</td><td>误触发/漏触发打断检测</td><td>轮次混乱、无效重置浪费算力</td></tr></tbody></table>\n<p>第三个边界是数据侧：全双工训练数据中重叠语音稀缺时，模型对“用户流仍在输入而助手流应继续”与“应立即让路”的判别退化为对能量的粗反应，表现为漏触发或误触发。这不是推理期能靠调度修补的，只能靠推理前的数据增强与阈值标定。规模上限因此不在单卡算力，而在双流 KV 显存与 SM 占用：并发会话数受 $M_{\\text{kv}}$ 与每会话常驻 SM 约束，用户流编码与助手流解码并行拓扑下，两路争抢同一批 SM 时需按块调度而非按请求调度，否则一个长用户流会话就能拖慢整批助手解码。</p>\n<h3 id=\"alg-dual-stream-full-duplex-sec-14\">十四 · 交错注意力的张量形状与掩码推导</h3>\n<p>核心公式 $h_t^{\\text{asst}}=\\mathrm{Attn}(q_t^{\\text{asst}},[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}])$ 里的 $\\oplus$ 不是简单拼接，而是沿序列维做一次带位置重映射的合并。推导的关键一步在于：三路 KV 各自携带自己的逻辑时间轴，合并前必须把用户流第 $i$ 帧、助手流第 $j$ 块、文本第 $k$ 个 token 映射到同一条交错序列位置 $p(i,j,k)$，否则注意力打分会在错误的相对距离上计算，助手流会把用户很早以前的语音当成紧邻上下文。设交错粒度为助手块长 $B_a$ 与用户帧块 $B_u$，则助手第 $t$ 步的可见集合是 $\\{p(i,j,k)\\le p_t\\}$ 且满足因果掩码，用户流在助手生成期间持续追加，故 $K^{\\text{user}}$ 的长度随会话单调增长，而 $K^{\\text{asst}}$ 在打断时被截断。</p>\n<p>把公式拆成三项代价：查询侧 $q_t^{\\text{asst}}$ 只一行，开销可忽略；KV 侧长度 $N=N_u+N_a+N_{\\text{text}}$ 决定注意力算术量为 $O(N)$ 每步、KV 读取带宽为 $2N d_h L$ 字节（$L$ 为层数）。以 FP16、头维 128、单层单头为例，每读取一个 KV 向量是 256 字节，$N$ 到万级时单步 KV 带宽已压过算力，这正是双流交错比单向流式 TTS 更早撞带宽墙的原因。工程含义是：交错顺序不只影响语义并行度，还直接决定 $N$ 的增长斜率，助手块越短、交错越细，$N$ 增长越快、每步带宽越高。</p>\n<div class=\"formula\">$$N_t = N_u(t) + N_a(t) + N_{\\text{text}},\\qquad \\Delta N_u = B_u,\\ \\Delta N_a = B_a$$</div>\n<p>具体例子：用户以 $B_u$ 帧块持续输入、助手以 $B_a$ 音频 token 块输出，若助手块长取大于用户帧块，则每轮交错只追加一次助手 KV，$N_a$ 斜率下降，但助手首块延迟上升；反之助手块短则打断响应快、带宽高。这个取舍就是交错粒度的调参本质，而不是模型结构问题。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-15\">十五 · 轮次延迟公式的逐项分解</h3>\n<p>$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a)$ 中三项对应三段流水，且 $\\text{streams}=2$ 表示用户编码与助手解码在时间上重叠，因此墙钟延迟不是三项之和而是关键路径。推导的关键一步是把 $t_{\\text{lm}}$ 写成 $t_{\\text{prefill}}(N) + B_a \\cdot t_{\\text{step}}$，其中 $t_{\\text{step}}$ 由解码阶段每步的 KV 带宽与 MMA 吞吐共同决定；$t_{\\text{voc}}(B_a)$ 则是声码器对 $B_a$ 个 token 的分块合成时间，可与下一块 LM 解码流水并行。于是端到端首块延迟为</p>\n<div class=\"formula\">$$L_{\\text{first}} = t_{\\text{enc}}(B_u) + t_{\\text{prefill}}(N_0) + t_{\\text{step}} + t_{\\text{voc}}(B_a)$$</div>\n<p>而稳态每块间隔为 $\\max(t_{\\text{step}}\\cdot B_a,\\ t_{\\text{voc}}(B_a))$，取大者决定吞吐节奏。这解释了为什么声码器分块合成若慢于 LM 解码，LM 会被反压、KV 继续增长、显存与带宽同时恶化；反之若声码器过快，则声码器空转、功耗浪费。工程判断是让 $t_{\\text{voc}}(B_a)$ 略小于 $B_a \\cdot t_{\\text{step}}$，把声码器放在流水下游而非瓶颈位。</p>\n<p>具体例子：打断场景下 $L_{\\text{turn}}$ 不适用，应改用打断响应时间 $L_{\\text{int}}=t_{\\text{det}}+t_{\\text{reset}}$，$t_{\\text{det}}$ 是检测窗内累计证据的判定延迟，$t_{\\text{reset}}$ 是助手 KV 截断与状态清空的重建时间。$t_{\\text{reset}}$ 与 $N_a$ 成正比，故助手流越长、打断越贵，这构成对助手最大连续输出长度的隐性约束。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-16\">十六 · KV 按流分区的显存账</h3>\n<p>双流交错使 KV 不能按单一序列线性管理。按流分区意味着为用户流、助手流、文本各分配独立的分页池，页表项记录逻辑位置到物理块的映射，注意力核在合并时按 $p(i,j,k)$ 顺序 gather。关键推导是显存占用 $M = L \\cdot d_h \\cdot s \\cdot (N_u+N_a+N_{\\text{text}}) \\cdot b$，$s$ 为 KV 头数、$b$ 为每元素字节数；用户流项 $N_u$ 随会话单调增长且不可回收，助手流项 $N_a$ 在打断时可整体释放，文本项 $N_{\\text{text}}$ 小但需与语音同步保留以维持语义对齐。</p>\n<p>失败模式的机理正在这里：若不分池，用户流持续增长会挤占助手流的物理块，分配器被迫为助手流做碎片整理或驱逐，表现为长会话下显存溢出或响应延迟上升。分池后需设配额 $Q_u+Q_a+Q_{\\text{text}}\\le M_{\\text{budget}}$，并在 $N_u$ 逼近 $Q_u$ 时触发用户流历史压缩（例如对远距离用户帧做下采样或摘要 token），这是把显存约束转成算法动作的标准做法。</p>\n<table class=\"mini\"><thead><tr><th>分区</th><th>增长特性</th><th>回收时机</th><th>主要代价</th></tr></thead><tbody><tr><td>用户流</td><td>单调增长</td><td>会话结束</td><td>带宽随 $N_u$ 线性上升</td></tr><tr><td>助手流</td><td>按块增长</td><td>打断即释放</td><td>重置重建延迟</td></tr><tr><td>文本</td><td>缓慢增长</td><td>随助手流同步</td><td>对齐一致性维护</td></tr></tbody></table>\n<p>具体例子：批内多个全双工会话共享 SM 时，批大小受双流 KV 显存约束而非算力约束，调度器应按各会话 $N_u$ 动态调整批组成，把长用户流的会话与短会话错峰，避免整批被单个长会话拖入带宽饱和。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-17\">十七 · 打断检测与 KV 重置的伪代码</h3>\n<p>打断判定不能只看单帧能量，需在检测窗内累计证据并与助手流当前输出状态联合判断。伪代码思路如下（文字描述，非代码块）：维护用户流最近 $W$ 帧的语义 token 与能量统计；每帧计算重叠得分 $s_t=\\alpha\\cdot\\text{energy}_t+\\beta\\cdot\\text{semantic\\_novelty}_t$；当滑动窗内 $\\sum s_t$ 超过阈值 $\\theta$ 且助手流处于输出中，则置打断标志；随后执行助手 KV 截断到最近一个安全块边界、清空助手解码状态、保留用户流 KV 与文本对齐指针，最后把助手流重新挂到用户流当前位置继续监听。</p>\n<div class=\"formula\">$$\\text{interrupt}_t=\\mathbb{1}\\Big[\\sum_{\\tau=t-W+1}^{t} s_\\tau&gt;\\theta\\Big]\\ \\wedge\\ \\text{asst\\_active}$$</div>\n<p>关键工程点是截断边界必须落在助手块边界上，否则声码器已送出的音频块与 KV 状态不一致，会出现旧回应残音。重置代价 $t_{\\text{reset}}$ 包含截断、页表回收、重新预填助手起始 token 三部分，其中页表回收在分池设计下是 $O(1)$ 量级，真正贵的是重新预填。阈值 $\\theta$ 设置不当的失败模式很直接：偏低则助手流被噪声误触发清空、对话轮次混乱；偏高则重置滞后、用户打断后仍输出旧回应，交互错位。</p>\n<p>具体例子：用户在中途插入短促否定词，语义新颖度项抬高 $s_t$ 但能量项不高，联合得分越过 $\\theta$ 触发打断；若只用电量阈值则漏检，助手继续输出与用户意图相反的回应。这说明 $s_t$ 的两项权重必须按数据增强后的重叠语音分布校准，而不是拍脑袋定值。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-18\">十八 · 文本桥接的注意力约束与可控生成</h3>\n<p>文本 token 作为内部桥梁，在公式中体现为 $K^{\\text{text}}$ 与 $V^{\\text{text}}$ 被助手流查询可见、同时约束用户流语义表征。推导的关键一步是给文本 KV 加一条对齐约束：助手音频 token 的隐状态需与同步文本 token 的隐状态在表示空间保持一致性，工程上以辅助损失或解码时的 logit 偏置实现，使语音与文本语义一致、便于可控生成。代价是文本 KV 虽短，却参与每一步注意力，等于给每步带宽加了一个固定小项 $2N_{\\text{text}}d_hL$，在 $N_{\\text{text}}$ 不大时可忽略，但若为可控生成塞入长提示文本，该项会显著抬高 $t_{\\text{step}}$。</p>\n<p>具体例子：需要助手以特定语气回应时，文本桥接让解码器在音频 token 与文本 token 间共享同一语义指针，字幕与语音同步输出；若文本 KV 与音频 KV 的时间轴未对齐，字幕会滞后于语音，破坏可控性。因此对齐指针在打断重置时必须与助手 KV 一同回滚，不能只清音频侧。</p>\n<p>工程判断落在交错顺序上：把文本 KV 放在用户流与助手流之间还是末尾，决定助手查询在相对位置上更靠近语义还是更靠近近期音频。靠近语义利于一致性，靠近音频利于即时反应；全双工场景通常取前者以稳住语义，把即时性交给用户流的持续更新来保证。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-19\">十九 · 交错注意力的边界：KV 分区、打断重置与重叠语音的失效面</h3>\n\n<p>把多流交错注意力写成可实现的形状，关键不在公式本身，而在 KV 的归属。助手流第 <em>t</em> 步的隐状态由三组 KV 拼接后做注意力得到：<div class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</div>其中拼接顺序决定听与说的并行程度——用户 KV 放在最前，助手流每步都要对持续增长的整段用户上下文做一次注意力，这是全双工“边听边说”的物理来源，也是代价的来源。工程上必须把三组 KV 按流分区管理：用户流 KV 随帧块单调增长、助手流 KV 随生成块增长、文本 KV 作为桥梁两者都读。若图省事把三流写进同一块连续显存池，用户流的长会话增长会直接挤占助手流的预留空间，表现为长会话下显存溢出或助手流解码步延迟抬升。分区后每流独立配额，用户流配额按最大监听窗口设上限，助手流按最大回复块设上限，文本 KV 跟随助手流生命周期。</p>\n\n<p>伪代码落到调度层，核心是一个双循环加一个中断标志：<ul><li>用户流编码循环按帧块产出语义/声学 token，写入用户 KV 分区，永不因打断而清空；</li><li>助手流解码循环每步读三组 KV 生成音频 token，送声码器流式解码，文本 token 同步出字幕；</li><li>打断检测在每帧块边界评估，命中则清空助手 KV 与文本 KV、重置助手流位置计数，用户 KV 与监听状态保留。</li></ul>这里的系统代价是显式的：两个循环共享同一 SM 池，用户流编码与助手流解码并行意味着每步都要为两套前向留出算力，批大小因此受双流 KV 显存而非单流显存约束；声码器流式解码与 LM 解码构成流水，声码器落后于 LM 时音频输出抖动，领先时又要缓存音频 token。打断响应时间由检测粒度决定——检测放在帧块边界而非 token 边界，是为了避免每 token 一次额外判断拖慢解码步，代价是打断延迟至少一个帧块。</p>\n\n<p>失效条件集中在两处。其一是打断阈值：阈值过松，重叠语音被误判为打断，助手流频繁清空，对话轮次碎裂；阈值过紧，清空与 KV 重置滞后，用户已开口而助手仍输出旧回应，交互错位在听感上比级联架构的更明显，因为全双工的旧回应与用户新语音在时间轴上直接重叠。其二是重叠语音数据稀缺：全双工训练样本中真正的双人同时说话比例低，模型在真实重叠语音下容易漏触发或误触发，表现为助手流该停不停、该续不续。这两类失效都不是靠调推理参数能修的，只能靠专门的数据增强与阈值标定，推理侧能做的是把打断判定与 KV 重置做成可观测事件，记录每次清空的触发时刻与残留助手 KV 长度，用于回归。适用边界因此清晰：低延迟、可打断的全双工对话是它的主场，并发会话数受 SM 与双流显存限制，长监听窗口与高并发不可兼得；一旦业务允许半双工轮替，单向流式的 KV 与注意力模式更简单、显存开销更低，此时多流交错的复杂度换不来对等收益。</p>\n<h3 id=\"alg-dual-stream-full-duplex-sec-20\">二十 · 什么样的请求形态才喂得饱双流引擎</h3>\n<p>双流全双工推理的负载配方，第一层判断不在长度，而在<strong>请求形态是否真的需要“同时听与说”</strong>。这套机制的成本结构由双流交错注意力决定：助手流每一步的隐状态都要对用户流 KV、助手流 KV、文本 KV 三路拼接做注意力，见 <span class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</span>。这意味着即使助手流此刻没有新 token 要出，用户流仍在按帧块推进、KV 仍在增长，计算图不能像单向流式 TTS 那样在句末收缩。于是负载配方要区分三类请求：一是真正的全双工会话——用户持续说话、助手按块输出、随时可被打断；二是半双工的“说完再答”请求，用户流在助手开口后即停止；三是纯合成请求，只有助手流。第三类请求跑在双流引擎上是纯浪费：它占着双流 KV 的显存分区却只用一路注意力，批里混入这类请求会拉低整批的有效算力密度。工程上应把纯合成流量路由到单向流式 TTS 路径，双流引擎只承接前两类，且优先第一类。</p>\n<p>请求形态还决定调度器要不要为“用户流持续输入”预留常驻槽位。全双工会话的用户流是长驻的，会话期间不会释放；如果调度器按“请求完成即回收”的常规连续批处理逻辑管理，就会把用户流当成一个永不完成的请求，导致批槽被长期占用、新会话排不进来。正确做法是把一次会话拆成两个生命周期：用户流槽位随会话建立与结束，助手流槽位随每个回应轮次建立与清空。打断时只重置助手流 KV、保留用户流状态，正是这一拆分的直接后果。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-21\">二十一 · 长度分布：用户流是长尾，助手流是短块</h3>\n<p>双流的长度分布不对称，这是负载配方里最容易被忽略的一条。用户流按帧块流入编码器，一个会话里用户可能说几秒也可能说几十秒，且中间有静默段；助手流则是按块自回归生成的短序列，每轮回应长度由文本 token 与音频 token 的块粒度决定。用轮次延迟公式看，<span class=\"formula\">$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a),\\quad \\text{streams}=2$$</span>，其中 $B_u$ 是用户帧块批、$B_a$ 是助手音频 token 批。$t_{\\text{enc}}$ 随用户流累积长度增长（注意力要对整段用户 KV 做），而 $t_{\\text{lm}}$ 与 $t_{\\text{voc}}$ 随助手块大小线性增长。两条曲线的最优点不在同一处：把 $B_u$ 调大能摊薄编码器的固定开销，但会让每个会话的用户 KV 更长、显存更紧；把 $B_a$ 调大能提高解码吞吐，但单块延迟上升，直接顶到端到端响应 SLO。</p>\n<p>因此长度分布的配方应按分位数而非均值设计。用户流长度取 P50 定常驻显存、取 P99 定溢出保护；助手流块长取固定小块以保证打断响应时间可控。若真实流量里用户长独白占比高（P99 远大于 P50），双流 KV 的显存预算会被少数长会话吃掉，此时要么对用户流做滑动窗口截断（牺牲远距离上下文），要么把长会话单独隔离到低并发池。反过来，若助手回应普遍很短而用户流频繁启停，则瓶颈落在编码器侧的批效率，应把多个会话的用户帧块合并成更大的 $B_u$ 批，而不是去调助手解码批。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-22\">二十二 · 并发与批大小：被双流 KV 显存钉死的上限</h3>\n<p>并发会话数不是由 SM 数量单独决定，而是由双流 KV 显存与带宽共同钉死。每个会话同时持有用户流 KV、助手流 KV、文本 KV 三份分区，且用户流分区随会话时长单调增长。设单会话用户流 KV 为 $S_u$、助手流 KV 为 $S_a$、文本 KV 为 $S_t$，则并发上限近似为 <span class=\"formula\">$$N_{\\text{conc}} \\approx \\frac{M_{\\text{kv}}}{S_u + S_a + S_t}$$</span>，其中 $M_{\\text{kv}}$ 是可用于 KV 的显存。分母里 $S_u$ 是变量，所以这个上限是随会话年龄衰减的：新会话涌入时按初始 $S_u$ 算出的并发数，在会话进行到中段后就不再成立。工程判断是给 $S_u$ 设一个硬上限（按 P99 用户流长度预留），超出即触发截断或迁移，否则显存会在长会话上缓慢泄漏式溢出。</p>\n<p>批大小的配方要按“流”分别定，而不是按请求定。助手流解码批 $B_a$ 受解码延迟 SLO 约束，通常取小块多批以维持打断响应；用户流编码批 $B_u$ 受编码器吞吐约束，可以取大。两者在同一个多流 Transformer 里交错输入，批维度上并不对齐，调度器需要维护两个独立的批队列并在注意力层做拼接。代价是注意力 kernel 的批形状不规则，tensor core 利用率下降，实际吞吐低于同参数的单流模型。带宽侧同样吃紧：双流交错使每步注意力要读三路 KV，KV 带宽需求约为单流的三倍量级，长会话下带宽而非算力先成为瓶颈。</p>\n<p>具体例子：一个客服场景，P50 用户流 8 秒、P99 用户流 40 秒，助手每轮回应按固定小块输出。若按 P50 预留 $S_u$ 并把并发开到显存允许的最大值，P99 会话一进来就会把该卡推到溢出边缘，表现为部分会话响应延迟突然抬升——这不是算力不够，是 KV 分区被长用户流挤占后触发了换出或重算。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-23\">二十三 · 负载不对时的三种典型塌陷</h3>\n<p><strong>其一，KV 未按流分区管理。</strong>用户流持续增长挤占助手流显存，长会话下显存溢出或响应延迟上升。这是双流引擎最典型的失败模式：如果 KV 池是单一共享池，用户流的单调增长会逐步压缩助手流的可用空间，助手解码步被迫等待显存回收，端到端延迟随会话时长爬升。配方上的对策是硬分区加配额，用户流分区独立核算、独立淘汰。</p>\n<p><strong>其二，打断检测阈值与负载不匹配。</strong>阈值过松时，真实打断被漏检，助手流继续输出旧回应，用户听到的是错位内容；阈值过紧时，背景噪声或用户停顿被误判为打断，助手流被频繁清空重来，轮次混乱且算力浪费在反复预填上。打断响应时间应作为独立 SLO 项纳入容量规划，因为它对应的是“清空助手 KV + 重建”的一次性开销，与常规解码延迟不同量纲。负载里重叠语音比例越高，这个阈值越难调，需要按流量画像分组配置而非全局一个值。</p>\n<p><strong>其三，重叠语音样本不足导致的触发失准。</strong>全双工训练数据稀缺，真实重叠语音下助手流误触发或漏触发。这不是推理期能修的，但推理配方可以通过负载侧的限制来兜底：对检测到高重叠率的会话降级为半双工模式（用户流暂停更新、助手说完再听），把不确定性挡在交互层之外，而不是让模型在没见过的重叠模式上自由发挥。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-24\">二十四 · 配方表的工程读法</h3>\n<p>把上述约束收拢成一张配方表，读法不是照抄数字，而是看每一行对应哪个代价项。请求形态决定路由与槽位生命周期；长度分布决定显存预留的分位数与截断策略；并发上限由双流 KV 显存与带宽共同给出且随会话年龄衰减；批大小按流分开定，助手批服从打断响应 SLO、用户批服从编码吞吐；SLO 以端到端响应延迟与打断响应时间双项衡量。任何一行配方改动，都要回到 $L_{\\text{turn}}$ 公式里看它动的是 $t_{\\text{enc}}$、$t_{\\text{lm}}$ 还是 $t_{\\text{voc}}$，以及它是否把压力转移到了 KV 显存或带宽上。</p>\n<table class=\"mini\"><thead><tr><th>配方维度</th><th>取值依据</th><th>对应代价项</th><th>失配后果</th></tr></thead><tbody><tr><td>请求形态路由</td><td>是否需同时听与说</td><td>算力密度</td><td>纯合成流量稀释批效率</td></tr><tr><td>用户流长度预留</td><td>P99 用户流长度</td><td>KV 显存</td><td>长会话溢出、延迟爬升</td></tr><tr><td>助手流块长</td><td>打断响应 SLO</td><td>解码延迟</td><td>打断滞后、输出错位</td></tr><tr><td>并发上限</td><td>双流 KV 显存与带宽</td><td>显存/带宽</td><td>随会话年龄衰减失效</td></tr><tr><td>打断阈值</td><td>流量重叠语音画像</td><td>重算开销</td><td>误触发或漏触发</td></tr></tbody></table>\n<p>最后落在一条具体机制上：双流引擎的调度器必须把“用户流槽位”与“助手流槽位”当作两种不同生命周期的资源来管理，前者按会话计、后者按轮次计，打断只回收后者。这条机制决定了并发上限的计算方式、决定了长度分布要按分位数预留、也决定了打断阈值必须作为独立 SLO 项进入容量规划——负载配方的一切失配，最终都表现为这两种槽位在显存与带宽上的争夺。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-25\">二十五 · 双流全双工的负载配方：什么请求形态吃得下，什么形态会把它压垮</h3>\n<p>这套方案的经济性建立在“用户流持续在跑、助手流按块吐出”的并发结构上，因此它对请求形态有明确的偏好：会话必须是长时、双向、可打断的实时语音，单轮时长足以摊薄双流 KV 的固定占用，且用户与助手的时间重叠比例高。若把短指令式请求（一问一答、每轮几百毫秒、用户说完即静默）灌进来，双流交错注意力的收益迅速消失——用户流在助手解码期间几乎不更新，却仍占据一份按流分区的 KV 与带宽预算，等于为闲置的并行通道付费。批大小因此不能按单流 LLM 的经验值线性放大：每增加一个会话，显存增量是两套流 KV 之和而非一套，调度器必须在“维持用户流编码”和“维持助手流解码”之间同时保留活跃状态，SM 占用被切成两半。用公式刻画单轮时延下界：</p>\n<div class=\"formula\">$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a),\\quad \\text{streams}=2$$</div>\n<p>其中 $B_u$、$B_a$ 分别是用户流帧块与助手流音频 token 块的批大小。注意 $t_{\\text{enc}}$ 与 $t_{\\text{lm}}$ 在时间上是重叠的（这正是全双工的意义），但两者共享同一批 SM 与显存带宽，所以真正决定 SLO 的不是单项之和，而是重叠区内的资源争抢。工程判断是：当重叠比例高、单轮足够长时，双流方案的单位会话成本低于级联；当重叠比例低、轮次极短时，级联 ASR/LLM/TTS 反而更省，因为它的每一段都能独立批处理到很大的批大小。这条边界应当在容量规划阶段就用会话时长分布与重叠率分布筛出来，而不是等线上延迟超标再回补。</p>\n<p>负载不对时的失效是分层的。第一层是显存：若双流 KV 未按流分区管理，用户流在长会话中持续增长，会挤占助手流的 KV 空间，表现为长会话后期显存溢出或助手流解码被拖慢、首 token 延迟上升——这不是模型问题，而是分区策略缺失。第二层是打断语义：打断检测阈值设置不当会让助手流清空与 KV 重置滞后，用户已经开口，系统仍在输出旧回应，交互出现明显错位；阈值过松则误触发，助手流被反复清空，轮次碎片化。第三层是数据分布：全双工训练数据中重叠语音样本不足时，真实重叠语音下助手流的触发判断失准，漏触发表现为“用户说话时助手沉默”，误触发表现为“用户未说完助手抢话”，两者都直接破坏对话轮次结构。这三层失效的共同点是：它们不会在标准单流基准上暴露，只在真实会话的长尾分布里出现。</p>\n<p>因此负载配方的核心不是“支持多少并发”，而是“在什么长度分布与重叠率分布下，双流 KV 的显存与带宽开销仍能被摊薄”。可操作的判据是：以会话为单位统计用户流活跃帧占比与助手流活跃帧占比，两者都高的会话才配得上双流并行；单侧长期静默的会话应降级到单流路径或级联路径，把省下的 KV 与带宽还给真正需要并行的会话。下表给出形态与代价的对应关系，用于调度侧的准入判断：</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>双流收益</th><th>主要代价</th></tr></thead><tbody><tr><td>长时双向、高重叠、频繁打断</td><td>高，端到端往返被消除</td><td>双流 KV 显存与带宽，需按流分区</td></tr><tr><td>短指令、低重叠、说完即静默</td><td>低，用户流多数时间闲置</td><td>为并行通道白付显存，批大小受限</td></tr><tr><td>重叠语音密集但数据稀缺</td><td>中，打断语义不稳</td><td>误触发/漏触发导致轮次混乱</td></tr></tbody></table>\n<p>落地时把这条判据写进准入与降级逻辑：会话建立时按历史长度分布与重叠率预估双流 KV 占用，超过显存水位即拒绝并行、改走单流；运行中监测用户流活跃帧占比，长期低于阈值则释放用户流 KV 分区，把带宽让给助手流解码。这样双流全双工的负载配方就不是一个固定并发数，而是一条随会话形态动态收缩的准入曲线——它保护的是重叠区内的资源争抢，而不是峰值并发本身。</p>\n<h3 id=\"alg-dual-stream-full-duplex-sec-26\">二十六 · 硬件档位的选取逻辑：从 SM 与显存带宽反推</h3>\n<p>双流全双工的部署档位不能按“模型参数量”一刀切，而要先看两个硬约束：一是助手流自回归解码的每步延迟，二是用户流编码与双流 KV 常驻的显存占用。Blackwell 上 tcgen05 与 TMEM 的引入让 MMA 吞吐与累加器驻留方式改变，但双流交错注意力的瓶颈往往不在算力，而在 KV 的读写带宽——助手流每步都要对 <span class=\"inline-code\">[K_user ⊕ K_asst ⊕ K_text]</span> 做一次完整注意力，用户流持续增长意味着这个拼接序列的长度单调上升，带宽需求随之线性增长。因此档位划分的第一维是显存容量与带宽，第二维才是 SM 数量。</p>\n<p>工程上可按并发会话数分三档：单卡档（单 GPU 承载少量会话，用户流与助手流同卡分区）、单节点档（多卡张量并行承载中等并发，声码器与 LM 分卡流水）、机架档（NVL72 内多节点，编码、LM、声码器三段分离部署）。判据是双流 KV 的常驻量：设每会话用户流 KV 为 <span class=\"inline-code\">S_u</span>、助手流为 <span class=\"inline-code\">S_a</span>、文本桥接为 <span class=\"inline-code\">S_t</span>，则单会话 KV 字节数近似为</p>\n<div class=\"formula\">$$M_{\\text{kv}} = 2 \\cdot L \\cdot H \\cdot d_h \\cdot b_{\\text{kv}} \\cdot (S_u + S_a + S_t)$$</div>\n<p>其中 <span class=\"inline-code\">L</span> 为层数、<span class=\"inline-code\">H</span> 为头数、<span class=\"inline-code\">d_h</span> 为头维、<span class=\"inline-code\">\\(b_{\\text{kv}}\\)</span> 为每元素字节数，前置因子 2 对应 K 与 V。这个式子决定了档位：若 <span class=\"inline-code\">S_u</span> 因长会话持续增长而主导，单卡档很快被挤爆，必须上单节点档做张量并行把每卡 KV 切片，或改用 KV 分页与用户流滑窗。例子：一个会话中用户流已累积到数千帧、助手流仅数十块时，KV 里用户流占比压倒性，此时张量并行切分的是头维而非序列维，序列维的压力只能靠分页与淘汰策略解决。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-27\">二十七 · 并行拓扑：编码、LM、声码器三段流水</h3>\n<p>部署拓扑的核心判断是：用户流编码与助手流解码必须并行，而不是串行排队。若把编码器与 LM 放在同一执行流里顺序调度，用户流每来一个帧块就要打断助手流的解码步，<span class=\"inline-code\">L_turn</span> 中的 <span class=\"inline-code\">t_enc</span> 会直接叠加到 <span class=\"inline-code\">t_lm</span> 上，全双工的并行收益归零。正确做法是三段分离：编码器独占一组 SM 或独立卡，LM 独占一组，声码器独占一组，段间以 token 队列衔接。</p>\n<p>伪代码思路如下：编码段持续消费音频帧块，产出语义 token 与声学 token 写入用户流队列；LM 段每步从队列取用户流增量、拼接助手流已生成 token 与文本桥接 token，执行交错注意力并采样助手 token；声码器段按块消费助手音频 token 流式合成。三段之间用有界队列做背压，队列深度即流水线缓冲，深度过大抬高 <span class=\"inline-code\">L_turn</span>，过小则编码抖动直接传导到解码。</p>\n<p>代价落在三处：一是段间传输，token 队列跨卡时走 NVLink 5，跨节点走 NCCL 或 NIXL 的 RDMA 路径，传输延迟计入端到端；二是 SM 争用，若三段共享同一 GPU，编码段的周期性突发会抢占 LM 解码的 SM，表现为解码步间隔抖动；三是声码器段的批合成与 LM 解码节奏不匹配时，声码器要么空转要么积压。例子：声码器按固定块长合成，而助手流 token 到达速率随文本桥接的语义密度波动，块长选大了首块播放延迟高，选小了合成调用频繁、SM 占用碎片化。工程判断是让声码器块长与 LM 解码步对齐到同一节拍，用双缓冲隐藏合成时间。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-28\">二十八 · 量化方案：FP16 主干与按流分区的 KV 精度</h3>\n<p>给定事实明确量化以 FP16 为主。这不是保守，而是双流交错注意力的数值敏感度决定的：用户流与助手流的 KV 在同一注意力里拼接，若两流用不同精度，拼接后的 softmax 归一化会引入流间偏置，表现为助手流对用户流的注意力权重系统性偏移。因此主干权重与激活统一 FP16，KV 也统一 FP16，不做逐流混合精度。</p>\n<p>真正可调的是 KV 的存储组织而非精度。按流分区管理意味着三块 KV 各自独立分页、独立增长、独立淘汰：用户流用滑窗加长尾压缩，助手流随生成推进单调增长但可整段丢弃（打断时清空），文本桥接 token 量小可常驻。分区的好处是打断时只释放助手流分页，用户流状态原地保留，避免整块 KV 重建带来的延迟尖峰。代价是分页表管理开销上升，注意力核需按三段拼接的物理布局做 gather，gather 的带宽开销在长序列下不可忽略。</p>\n<p>若要在显存上进一步压缩，可对用户流的声学 token KV 做低比特驻留、需要时上采样回 FP16 参与注意力，但这会引入反量化延迟，且与 tcgen05 的 MMA 输入格式对齐要求冲突，工程上只在显存确实溢出时才启用。例子：长会话中用户流 KV 占满单卡剩余显存时，先启用用户流滑窗丢弃最老帧块，再考虑声学 KV 低比特驻留，顺序不能反——滑窗是语义无损的（远距离语音对当前回应贡献低），低比特是有损的。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-29\">二十九 · KV 策略：分区、滑窗与打断重置</h3>\n<p>KV 策略要同时满足三个目标：用户流可无限增长而不挤占助手流、打断时助手流可瞬时清空、文本桥接始终可寻址。实现上把 KV 池划为三个独立区域，各自有独立的分配器与淘汰器。用户流区域采用环形缓冲加滑窗注意力，窗口外的帧块只保留压缩摘要（如对语义 token 做池化），保证远距离上下文以低带宽代价参与；助手流区域按生成块追加，打断信号到达时整区标记失效并归还分页，不做逐块释放；文本桥接区域小且稳定，常驻不淘汰。</p>\n<p>打断重置的关键是原子性：助手流 KV 失效与助手流解码停止必须同一时刻生效，否则会出现“已重置 KV 但仍在用旧 KV 解码”的窗口，输出旧回应。工程上用版本号标记助手流 KV，解码步携带版本号，版本不匹配即丢弃该步输出。代价是每次解码多一次版本比对，可忽略；收益是打断响应时间由“等待当前解码步完成”降为“下一步即生效”。</p>\n<p>失败模式在此处最典型：未按流分区时，用户流持续增长会挤占助手流显存，长会话下显存溢出或响应延迟上升；分区后若滑窗淘汰策略过于激进，用户流摘要丢失导致助手流误判用户意图。例子：用户连续说话数十秒，用户流 KV 线性增长，若与助手流共享同一池且无淘汰，助手流新块分配失败触发重分配，表现为解码步延迟突然抬升；分区加滑窗后该现象消失，但窗口长度需按语义 token 的有效上下文跨度设定，设得过短则打断后的续听丢失前文。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-30\">三十 · 调度参数：批大小、队列深度与打断阈值</h3>\n<p>调度参数围绕一个矛盾展开：批大小受双流 KV 显存约束，而全双工会话的请求到达是持续的、非批式的。连续批处理在这里的形态是“流式批”——每个解码步把当前所有活跃会话的助手流一步合并成一个批，用户流编码则按帧块到达独立调度。批大小上限由 <span class=\"inline-code\">\\(M_{\\text{kv}}\\)</span> 与显存余量反推，而非由算力决定；超过上限时新会话排队，排队即抬高首响应延迟。</p>\n<p>需要显式设置的参数有三类。其一是解码批的组成策略：优先合并处于相同解码阶段的会话以减少填充浪费，打断中的会话单独成小批以快速响应。其二是编码队列深度：深度决定用户流增量到达 LM 的滞后，滞后直接计入 <span class=\"inline-code\">t_enc</span> 到 <span class=\"inline-code\">t_lm</span> 的衔接。其三是打断检测阈值：阈值过低会把用户流的正常停顿误判为打断，触发不必要的助手流清空；阈值过高则重置滞后，用户打断后仍输出旧回应。阈值应结合用户流能量与语义 token 的突变联合判定，而非单看能量。</p>\n<p>代价权衡很直接：批越大，单步解码的 KV 带宽占用越高，解码步延迟上升，端到端响应延迟随之上升；批越小，SM 利用率下降，吞吐掉。全双工的 SLO 以端到端响应延迟与打断响应时间衡量，二者对批大小的敏感方向相反——响应延迟偏好小批，吞吐偏好大批。工程判断是按 SLO 反推批上限，把打断响应时间作为硬约束优先满足，吞吐在其后优化。例子：打断响应时间要求苛刻时，把打断中的会话从主批摘出单独解码，主批继续服务其他会话，牺牲少量吞吐换取打断路径的确定性延迟。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-31\">三十一 · 可复现的配置思路：从约束到参数的推导链</h3>\n<p>给出一条不依赖具体数字的推导链，便于在不同硬件上复现。第一步定并发目标与 SLO：端到端响应延迟上限与打断响应时间上限。第二步按 <span class=\"inline-code\">\\(M_{\\text{kv}}\\)</span> 公式估算单会话 KV 常驻，结合目标并发反推所需显存，确定档位（单卡/单节点/机架）。第三步按档位定并行拓扑：单卡档三段共享 SM 但用独立执行流与有界队列隔离；单节点档编码与声码器各占一卡、LM 张量并行；机架档三段分节点，段间走 NIXL。第四步定 KV 分区与滑窗长度，滑窗长度按语义 token 有效跨度取，助手流整段可弃。第五步定量化：主干与 KV 统一 FP16，仅在显存溢出时启用用户流声学 KV 低比特驻留。第六步定调度：批上限由显存余量反推，打断会话单独成批，编码队列深度取能隐藏编码抖动的下限，打断阈值联合能量与语义突变判定。</p>\n<p>验证顺序也有讲究：先压测单会话的 <span class=\"inline-code\">L_turn</span> 分解，确认 <span class=\"inline-code\">t_enc</span>、<span class=\"inline-code\">t_lm</span>、<span class=\"inline-code\">t_voc</span> 三段各自占比，找出主导项；再压并发，观察 KV 增长曲线与解码步延迟的关系，确认滑窗与分区生效；最后注入打断，测打断响应时间与旧回应残留。任一步失败都指向具体机制：<span class=\"inline-code\">t_enc</span> 主导说明编码段 SM 不足或队列滞后；解码步延迟随会话时长上升说明用户流 KV 未分区或滑窗失效；打断残留说明版本号机制缺失或阈值滞后。</p>\n<p>最后落在工程判断上：双流全双工的部署配方里，唯一不能妥协的是 KV 的按流分区与打断的原子重置——前者决定长会话能否稳定运行，后者决定全双工的交互语义是否成立。量化与并行拓扑是可调的效率杠杆，调度参数是可调的 SLO 杠杆，而分区与原子性是正确性前提，调错即失败模式直接显形。</p>\n<h3 id=\"alg-dual-stream-full-duplex-sec-32\">三十二 · 双流 KV 的显存账：谁在挤占谁</h3>\n<p>全双工推理的显存结构不同于单向流式解码。单向场景里只有一条自回归序列在增长，KV cache 是一条单调递增的线性表；双流场景里，用户流的 KV 随用户持续说话而增长，助手流的 KV 随助手按块输出而增长，两者共享同一个注意力窗口却必须分开管理。交错注意力 $h_t^{\\text{asst}}=\\mathrm{Attn}(q_t^{\\text{asst}},[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}])$ 中的拼接操作在物理上不是一次真实的内存拼接，而是三段独立分区的逻辑视图，分区边界决定了显存分配器的行为。</p>\n<p>代价首先体现在碎片化。用户流按帧块流入，块长固定但会话时长不定；助手流按输出块增长，块数取决于回应长度。若两者共用一块连续 KV 缓冲，用户流的长会话会把助手流的预留空间挤到高地址端，导致助手流每次追加块都可能触发重分配或拷贝。工程上的做法是按流分区：用户流与助手流各自持有独立的 KV 池，文本 token 的 KV 作为第三个小分区常驻，注意力核在读取时按三段基址分别寻址。这样做的显存代价是分区带来的对齐浪费，收益是长会话下不会出现“用户流把助手流挤爆”的失败模式——这正是双流交错 KV 未分区时的典型崩溃点。</p>\n<p>具体例子：一个会话中用户连续说话数十秒，用户流 KV 持续增长，而助手流在等待打断检测的间隙保持静止。若分区缺失，显存分配器会把助手流的块视为可回收，下一次助手流恢复输出时被迫重新分配并可能溢出。分区后，用户流的增长只消耗自己的池，助手流的池在打断重置时整体释放，显存曲线呈锯齿而非单调爬升。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-33\">三十三 · 带宽：交错注意力的读放大</h3>\n<p>交错注意力的算术强度低于单向解码。单向解码每步只读一条序列的 KV，双流解码每步要读三段 KV：用户流、助手流、文本。设三段长度分别为 $n_u$、$n_a$、$n_t$，每步注意力的 KV 读取量为 $(n_u+n_a+n_t)\\cdot d\\cdot 2$ 字节（FP16 下每元素 2 字节，K 与 V 各一份），而有效计算只有一次 $q$ 与拼接 KV 的乘加。读放大系数约为三段长度之和与单段长度之比，用户流越长，放大越明显。</p>\n<div class=\"formula\">$$R_{\\text{bw}}=\\frac{(n_u+n_a+n_t)\\,d\\,2}{n_a\\,d\\,2}=1+\\frac{n_u+n_t}{n_a}$$</div>\n<p>这个比值直接决定了解码步的带宽瓶颈位置。当 $n_u\\gg n_a$（用户长说、助手短答），$R_{\\text{bw}}$ 远大于 1，注意力核的耗时由 HBM 读取主导而非 tensor core 计算。工程判断是：双流解码不应追求大 batch 的算力打满，而应追求 KV 读取的合并效率——把用户流与助手流的 KV 在物理上放在同一 HBM 页附近，减少三段基址跳转带来的行激活开销。代价是布局灵活性下降，收益是每步解码的带宽占用可控。</p>\n<p>具体例子：助手流刚开始输出时 $n_a$ 很小，$R_{\\text{bw}}$ 被用户流长度主导，此时若把助手流的输出块做得过小，每步都要重读整段用户 KV，带宽被反复消耗；把助手流的块长调大，单步读取摊薄到更多输出 token 上，带宽效率回升，但首块延迟上升。这是全双工里块长与带宽的直接权衡。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-34\">三十四 · 通信：打断重置的同步代价</h3>\n<p>双流推理在单卡内是显存与带宽问题，跨卡后变成通信问题。用户流编码与助手流解码在并行拓扑上分属不同阶段，用户流的帧块需要从编码侧送到解码侧的注意力核，助手流的输出块需要送到声码器流水。NVLink 5 的带宽足以承载单会话的 token 流，但打断事件是同步点：打断检测触发助手流清空与 KV 重置，这个动作要求所有持有助手流 KV 分区的 rank 同时释放并确认，保留用户流状态继续监听。同步的代价不是带宽而是尾延迟——重置指令的传播延迟决定了打断响应时间的下界。</p>\n<p>伪代码思路：打断处理不是立即清空，而是标记助手流分区为待回收，在下一个解码步开始前统一释放，避免在解码中途插入同步屏障。这样做的代价是重置滞后一个解码步，收益是不打断正在进行的注意力核。工程上把打断检测的阈值与重置的粒度解耦：检测可以激进，重置必须对齐到块边界。</p>\n<p>具体例子：多卡部署下用户打断，助手流 KV 分布在多个 rank 上，若逐 rank 同步清空，尾延迟由最慢 rank 决定；若改为块边界统一释放，尾延迟被压到一个解码步的量级。失败模式是阈值设置不当导致重置滞后，用户打断后仍输出旧回应，交互错位——这不是带宽问题，是同步时序问题。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-35\">三十五 · 功耗与 SM 占用：双流并行的常驻成本</h3>\n<p>全双工意味着用户流编码与助手流解码同时常驻。单向流式在等待用户输入时可以降频或让出 SM，双流不能：用户流持续流入编码器，助手流在打断间隙也要保持 KV 与注意力状态。SM 占用是常驻的，功耗曲线是平的而非脉冲式的。这对容量规划的影响是：并发会话数受 SM 与显存双重限制，而不是单纯受显存限制。</p>\n<p>代价体现在能效比上。双流并行时每个会话占用的 SM 时间片包含用户流编码的固定开销，这部分开销不随助手输出长度变化，属于沉没成本。规模上去后，先崩的往往不是显存而是 SM 调度：当并发会话数接近 SM 能承载的上限，用户流编码的固定开销把可用算力吃掉，助手流的解码步被推迟，端到端响应延迟 $L_{\\text{turn}}=t_{\\text{enc}}(B_u)+t_{\\text{lm}}(B_a)+t_{\\text{voc}}(B_a)$ 中的 $t_{\\text{lm}}$ 因调度排队而膨胀。</p>\n<p>具体例子：并发会话从少量增加到接近 SM 上限时，显存尚有余量但解码步的排队时间上升，表现为响应延迟的非线性增长。工程判断是把用户流编码与助手流解码放在不同的 SM 分区或不同的流水阶段，避免编码的固定开销侵占解码的算力预算。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-36\">三十六 · 尾延迟：规模上去后先崩的位置</h3>\n<p>尾延迟的来源在双流场景里比单向多一个维度：除了常规的解码步长尾，还有打断响应的长尾。打断响应时间由检测延迟、重置同步延迟、助手流首块生成延迟三段构成，任一段出现长尾都会把 P99 拉高。规模上去后，先崩的位置按顺序通常是：KV 分区碎片化导致的重分配尖峰、打断重置的跨 rank 同步、SM 调度排队。显存溢出是最后才出现的，因为分区管理把溢出转化成了延迟尖峰而非直接 OOM。</p>\n<p>工程判断是给打断响应单独设 SLO，不与端到端响应延迟混在一起统计。端到端延迟衡量的是正常轮次的 $L_{\\text{turn}}$，打断响应衡量的是从检测到助手流清空并恢复监听的时间。两者混统计会让尾延迟指标失真：正常轮次的长尾被打断事件掩盖，打断的长尾被平均掉。分开统计后，容量规划才能定位是先扩 SM 还是先改 KV 分区策略。</p>\n<p>具体例子：长会话下用户流 KV 持续增长，若分区池按固定上限分配，接近上限时每次追加块都触发碎片整理，表现为周期性延迟尖峰；把用户流池改为按会话动态伸缩、助手流池按块预分配，尖峰被摊平。这是规模上去后最典型的先崩点——不是算力不够，是显存管理策略在长会话下失效。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-37\">三十七 · 容量规划的落点：按流分账</h3>\n<p>双流全双工的容量规划不能按单一会话的显存均值乘以并发数来算。用户流与助手流的增长速率不同、生命周期不同、重置行为不同，必须按流分账：用户流池按最长会话时长与帧块速率估算上限，助手流池按最大回应块数估算，文本 KV 作为小常数项。并发会话数的上限取三者中最先触顶的那个，而不是总和。</p>\n<p>这个分账方式直接对应失败模式的预防：用户流持续增长挤占助手流显存的场景在分账下不会发生，因为两个池物理隔离；打断重置滞后的场景在分账下表现为助手流池的释放时机问题，可以在块边界统一处理。规模上去后，容量规划的落点不是堆显存，而是把 KV 分区策略、打断同步粒度、SM 分区三件事对齐到同一套按流分账的预算上。数据稀缺导致的重叠语音鲁棒性不足是另一类问题，它影响的是检测阈值而非容量，阈值不当会让重置频繁触发，间接推高助手流池的分配抖动——这仍然落在按流分账的框架内可诊断。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-38\">三十八 · 双流 KV 的显存墙与规模崩塌点</h3>\n<p>全双工推理的系统代价首先落在 KV cache 的分区管理上。多流交错注意力把用户流、助手流与内部文本 token 的 KV 拼成一条联合序列：$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$，其中 $\\oplus$ 不是免费拼接——它要求三组 KV 在物理上可寻址、在逻辑上按交错顺序排列，任何一次拼接都意味着一次额外的索引重排与显存搬运。用户流在会话存续期间单调增长，助手流在每轮打断时被清空重置，文本流随字幕同步推进；三条流生命周期不同步，若 KV 未按流分区管理，用户流的持续增长会直接挤占助手流预算，长会话下先出现显存溢出，再表现为解码步延迟爬升。这是规模上去以后第一个崩的地方：不是算力不够，而是显存与带宽被一条只增不减的流吃掉。</p>\n<p>把代价写成可核算的形式：单会话 KV 字节数近似为 $2 \\cdot L_{\\text{ctx}} \\cdot d \\cdot b_{\\text{kv}} \\cdot n_{\\text{streams}}$，双流即 $\\text{streams}=2$，再叠加文本桥接的少量 KV。批大小 $B$ 因此不是由 LM 权重决定，而是由双流 KV 显存约束反解出来；并发会话数同时受 SM 占用与显存上限夹逼。带宽侧更隐蔽：交错注意力每步都要在用户流新块与助手流历史之间做交叉读取，KV 读取量随上下文线性增长，而助手流每生成一个音频块只推进极短一步，算术强度被压得很低，解码阶段实际是带宽受限而非算力受限。一个具体例子：长会话中用户流已累积到数千帧、助手流刚被重置，此时一次解码步的 KV 读取几乎全部来自用户流历史，注意力算力利用率骤降，尾延迟由 HBM 带宽而非 tensor core 决定。</p>\n<p>尾延迟的第二个来源是打断路径。打断检测触发助手流清空与 KV 重置、保留用户流状态继续监听，这个动作本身是一次显存批量释放加索引重建，若阈值设置不当、重置滞后，用户打断后系统仍按旧 KV 输出旧回应，交互错位表现为可感知的尾延迟尖峰而非平均值恶化。调度器必须同时维持用户流编码与助手流解码两条流水，声码器流式解码又与 LM 解码串联，任何一环阻塞都会把尾延迟推到 SLO 之外。规模上去后先崩的顺序是：显存（KV 分区不足）→ 带宽（交错读取的算术强度过低）→ 尾延迟（打断重置与流水阻塞），通信与功耗在此方案中相对次要，因为双流推理以单机单卡内数据流为主，NVLink 与跨节点通信只在多会话聚合时才进入瓶颈。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>先崩的资源</th><th>触发条件</th></tr></thead><tbody><tr><td>单会话时长</td><td>显存</td><td>用户流 KV 单调增长、未分区隔离</td></tr><tr><td>并发会话数</td><td>显存 + SM</td><td>双流 KV 与编码/解码并行争用</td></tr><tr><td>打断频率</td><td>尾延迟</td><td>KV 重置滞后、流水阻塞</td></tr></tbody></table>\n<h3 id=\"alg-dual-stream-full-duplex-sec-39\">三十九 · 精度漂移：从 FP16 到低比特的静默失效</h3>\n<p>双流全双工的精度问题与单向 TTS 不同：它同时存在两条数值路径——用户流编码器持续吃进帧块、助手流自回归吐音频 token，而文本 token 作为内部桥梁横跨两者。任何一侧的量化误差都会通过交错注意力放大到另一侧。典型失效不是崩溃，而是\"静默漂移\"：助手流生成的音频 token 分布逐渐偏离训练分布，表现为韵律塌陷、字词吞音、或对用户流语义 token 的注意力权重变平（听而不闻）。诊断入口是交错注意力的 KV 分区统计：</p>\n<div class=\"formula\">$$\\Delta_t=\\big\\|h_t^{\\text{asst}}-\\hat h_t^{\\text{asst}}\\big\\|_2,\\quad \\hat h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[\\hat K^{\\text{user}}\\oplus\\hat K^{\\text{asst}}\\oplus\\hat K^{\\text{text}}],\\,[\\hat V^{\\text{user}}\\oplus\\hat V^{\\text{asst}}\\oplus\\hat V^{\\text{text}}]\\big)$$</div>\n<p>把 $\\Delta_t$ 按流分别累计，若用户流 KV 量化后 $\\Delta$ 增长显著快于助手流，说明编码器侧的低比特格式（如微缩放格式）在重叠语音帧上失稳；若文本 KV 侧偏差主导，则是内部对齐桥梁被量化破坏，语音与字幕会不同步。工程代价上，精度回滚不是免费的：从低比特切回 FP16 会使双流 KV 显存近似翻倍，直接压缩批大小上限，吞吐下降。因此监控必须做到按流、按 token 类型分桶，而不是只看整模型 loss。一个具体例子：长会话中助手流开始重复短句，排查发现是文本 token KV 在低比特下注意力 logits 饱和，回滚文本 KV 至 FP16、保留音频 KV 低比特，即恢复且显存只增一小块。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-40\">四十 · OOM 的真实来源：用户流挤占助手流</h3>\n<p>双流 KV 未按流分区管理是本算法最典型的 OOM 路径。用户流在会话全程持续增长（用户不说话时也在编码静音/环境帧），助手流则在打断时被清空重置。若两者共享一个线性增长的 KV 池，长会话下用户流会逐步吃掉助手流的预留空间，表现为\"越聊越慢\"再到分配失败。诊断信号是分区水位比：</p>\n<div class=\"formula\">$$\\rho=\\frac{M^{\\text{user}}_{\\text{kv}}}{M^{\\text{user}}_{\\text{kv}}+M^{\\text{asst}}_{\\text{kv}}+M^{\\text{text}}_{\\text{kv}}},\\quad \\text{alert if }\\rho&gt;\\rho_{\\max}\\ \\text{且}\\ M^{\\text{asst}}_{\\text{kv}}\\ \\text{余量}&lt;B_a$$</div>\n<p>其中 $B_a$ 是助手流单块解码所需的最小 KV 余量，与 $L_{\\text{turn}}=t_{\\text{enc}}(B_u)+t_{\\text{lm}}(B_a)+t_{\\text{voc}}(B_a)$ 中的 $B_a$ 同源。监控应把 $\\rho$ 与助手流余量做成双阈值：$\\rho$ 高但余量足，只是效率问题；余量跌破 $B_a$ 则是硬故障前兆，必须触发用户流 KV 的滑窗截断或会话迁移。代价上，滑窗截断会丢失早期对话上下文，影响指代消解；会话迁移则要重放用户流状态，产生一次显存与带宽尖峰。具体例子：某会话在连续监听 20 分钟后助手流分配失败，日志显示 $\\rho$ 单调上升而助手 KV 余量在打断重置后未回收干净——根因是重置只清了助手 KV 指针却未归还池，修复为按流独立池加引用计数回收。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-41\">四十一 · 批抖动与路由不均</h3>\n<p>全双工会话的批组成天然不稳定：用户流持续输入意味着每个请求始终\"活着\"，而助手流按块输出、打断时清空，导致同一批内各序列的解码步数、KV 长度、剩余生成长度差异巨大。连续批处理若按到达顺序贪心组批，会出现批抖动——批内最慢序列（通常是刚被打断重置、需重新预填助手流的会话）拖住整批，吞吐随会话阶段剧烈波动。诊断指标是批内解码步数方差与\"空转比\"（批中因等待而未被利用的槽位比例）。路由不均则出现在多副本部署：打断频繁的会话被哈希到同一副本，该副本助手流重置风暴集中，尾延迟抬升。缓解手段是按流状态做亲和路由，把\"正在被打断重置\"的会话与\"稳定长解码\"的会话分散到不同副本，并对重置后的助手流预填单独走小批快速通道。代价是路由表维护与跨副本状态同步开销；具体例子：把打断率作为路由权重后，单副本重置风暴被摊薄，批内方差下降，尾延迟尖刺收敛。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-42\">四十二 · 尾延迟尖刺：打断滞后与声码器流水断流</h3>\n<p>尾延迟尖刺有两个专属来源。其一是打断检测阈值不当：助手流清空与 KV 重置滞后，用户已开口而模型仍在输出旧回应，交互错位；监控应记录\"检测到打断→助手流首 token 停止\"的滞后分布，而非平均延迟。其二是声码器流式解码与 LM 解码的流水断流：助手音频 token 按块送声码器，若 LM 侧因批抖动出现长间隔，声码器无块可合成，播放端出现可闻的停顿。诊断用流水填充率：</p>\n<div class=\"formula\">$$\\text{fill}=\\frac{\\sum_k \\min(n^{\\text{voc}}_k,\\,n^{\\text{lm}}_k)}{\\sum_k n^{\\text{lm}}_k},\\quad \\text{spike if }\\text{fill}\\ \\text{在窗口内骤降}$$</div>\n<p>填充率骤降说明 LM 解码供给不足，应优先排查批抖动与助手流重置风暴，而不是调声码器。代价上，为压尾延迟而缩小批或提高打断灵敏度，会牺牲吞吐并增加误触发（把用户呼吸/背景音判为打断），形成\"灵敏—误触发\"权衡。具体例子：尾延迟 P99 尖刺与填充率低谷时间对齐，定位到某副本助手流集中重置导致 LM 供给断档，改为重置请求走独立小批后尖刺消失。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-43\">四十三 · 监控分层与回滚策略</h3>\n<p>监控按三层组织，每层对应一类失败模式。会话层：$\\rho$ 水位、助手 KV 余量、打断滞后分布、轮次混乱率（重叠语音下误触发/漏触发计数）。批层：批内解码步数方差、空转比、流水填充率。数值层：按流的 $\\Delta_t$、文本 KV 注意力熵。回滚要分级且可局部化：数值层回滚只切某条流的量化格式（如文本 KV 回 FP16），不动批与路由；批层回滚关闭激进组批、恢复按流状态亲和路由；会话层回滚则是降并发上限、缩短用户流 KV 滑窗。回滚触发条件写成组合判据而非单指标，避免抖动误回滚：例如 $\\rho$ 超阈且助手余量跌破 $B_a$ 连续若干窗口才执行。代价是回滚本身引起容量重算——FP16 回滚使双流 KV 显存上升，必须同步下调并发会话数以守住 SLO，这一步若不联动，回滚会把 OOM 换成超时。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-44\">四十四 · 工程判断：把失败模式绑到流分区上</h3>\n<p>本算法的失败模式几乎都能追溯到同一个结构事实：双流交错使 KV 与注意力模式复杂，用户流与助手流的生命周期不对称（前者只增，后者可重置）。因此诊断的第一原则是按流分区观测，任何全局指标都会掩盖单流故障。第二原则是把打断重置当作一等事件：它同时是延迟尖刺源、批抖动源和显存回收漏点，监控必须覆盖\"重置发起—KV 归还—助手流重新预填\"的完整链路，而不是只看重置次数。第三原则是回滚粒度与流绑定：能只回滚文本 KV 就不回滚整模型，能只调路由就不动量化。在并发会话数受 SM 与显存约束的部署下，这套分层监控与分级回滚是把\"能跑\"维持成\"跑得稳\"的实际抓手——尤其当全双工训练数据稀缺、重叠语音鲁棒性本就偏弱时，监控里那条轮次混乱率曲线往往比任何延迟指标更早预示系统性退化。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-45\">四十五 · 双流全双工推理的失效边界：显存挤占、打断错位与尾延迟尖刺</h3>\n\n<p>双流方案最隐蔽的失效不是算错，而是<strong>KV 分区失衡</strong>。用户流持续流入、助手流按块自回归，两者共享同一组交错注意力的 KV 池；若未按流做硬分区，用户流的历史帧会单调增长并挤占助手流的可分配块。长会话下，助手流每次 decode 需要拼接 <span class=\"formula-inline\">[K_user⊕K_asst⊕K_text]</span>，其注意力读取带宽随用户流长度线性上升，而可用显存块却在收缩，最终表现为两条曲线交叉：一条是延迟上升，一条是 OOM。工程上应把用户流 KV 设为环形缓冲并绑定固定上限，助手流 KV 按会话生命周期独立计费，文本 token KV 单独小池；三者任一超限即触发该会话降级（缩短用户流窗口或降低助手流块大小），而不是让整卡 OOM 拖垮同批其他会话。监控指标应直接采<em>每流 KV 占用比</em>与<em>每步注意力读取字节数</em>，而非只看整卡显存水位——后者在挤占初期毫无反应。</p>\n\n<p>第二个失效点是<strong>打断检测与 KV 重置的时序错位</strong>。打断判定若放在声码器播放侧，检测到用户语音时助手流已多生成了若干音频块，清空滞后导致用户听到旧回应尾音，交互错位比纯延迟更伤体验。正确做法是把检测前移到用户流编码器输出，用语义 token 与声学 token 的联合置信度做门控，一旦判定打断立即冻结助手流自回归、丢弃未送声码器的待播块、重置助手 KV 并保留用户流状态。这里有一个可量化的代价公式：打断响应时间 <span class=\"formula-inline\">t_br = t_det + t_reset + t_first</span>，其中 <span class=\"formula-inline\">t_reset</span> 是助手 KV 释放与重建首块的开销，<span class=\"formula-inline\">t_first</span> 是新回应首块解码时间。阈值设得过松会漏触发，设得过紧则用户换气、咳嗽都被判为打断，助手流反复清空导致轮次混乱——这正是重叠语音数据稀缺时的典型表现：模型没见过足够多的“用户说话中助手该不该停”样本，门控分布偏移。诊断手段是记录每次打断前后的 <span class=\"formula-inline\">t_det</span> 分布与误触发率，把门控阈值当作可回滚的运行时参数而非编译期常量。</p>\n\n<p>第三个失效是<strong>批抖动与路由不均</strong>。全双工会话的请求形态是“用户流持续输入、助手流按块输出”，批内各会话的助手流解码步数差异极大：有的会话正在长回答，有的刚被打断只剩用户流编码。若调度器按统一批大小硬凑，短会话被长会话拖住，尾延迟尖刺来自批内最慢那条。更麻烦的是双流交错使注意力模式随批内流组合变化，同一 kernel 在不同批构成下 SM 占用率波动，路由到不同 SM 组的会话出现系统性快慢差。缓解办法是把用户流编码与助手流解码拆成两条独立调度队列，编码队列按帧块到达节奏做小批聚合，解码队列按连续批处理动态增删；打断时只从解码队列摘除该会话，编码队列不动。监控应采<em>批内解码步数方差</em>与<em>每 SM 组完成时间分位差</em>，方差突增即说明批构成劣化，需触发重排而非扩容。</p>\n\n<p>精度问题在本方案里主要来自文本 token 内部对齐的数值一致性：语音 token 与文本 token 共享注意力但走不同量化路径时，FP16 主路径下若对文本 KV 单独降精度，语义桥梁会漂移，表现为字幕与语音内容轻微不符。回滚策略应分层：先回滚调度参数（批大小上限、打断阈值、用户流窗口），再回滚 KV 分区配比，最后才回滚量化配置；每次回滚只动一层并保留会话级灰度，因为双流方案的失效往往是多因素耦合，一次性全量回滚会掩盖真正的根因。诊断面板上至少并列三条曲线：每流 KV 占用、打断响应时间分位、批内解码步数方差，任一越界即定位到对应层。</p>\n<h3 id=\"alg-dual-stream-full-duplex-sec-46\">四十六 · 对照轴：三条正交维度而非一条“先进度”</h3>\n<p>选型时最容易犯的错，是把全双工多流 Transformer 与级联 ASR/LLM/TTS、单向流式 TTS 排成一条“先进度”直线，然后取最右端。工程上真正决定取舍的是三条彼此正交的轴：<strong>并行度</strong>（用户流与助手流是否在同一模型内同时前向）、<strong>对齐载体</strong>（文本 token 作为内部桥梁，还是外部串接的文本接口）、<strong>状态可重置性</strong>（打断时能否只清空一侧 KV 而保留另一侧）。全双工多流方案在三条轴上分别取“同模型并行 / 内部文本对齐 / 按流分区重置”，级联方案取“串行 / 外部文本接口 / 整链重启”，单向流式 TTS 取“仅助手流 / 无用户流 / 无打断语义”。任何一条轴上的降级都会直接反映到 <span class=\"formula\">$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a),\\quad \\text{streams}=2$$</span> 的某一项上：级联把 $t_{\\text{enc}}$ 与 $t_{\\text{lm}}$ 拆成两次独立往返，单向流式 TTS 则根本没有 $B_u$ 这一项，因此谈不上打断。</p>\n<p>对照的目的不是选出“最强”，而是判断在给定 SLO 与显存预算下，哪条轴上的收益值得付出哪条轴上的代价。下面三节分别给出这三条轴的判据，最后一节把它们压成一张决策表。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-47\">四十七 · 并行度轴：端到端往返次数与 KV 复杂度的交换</h3>\n<p>级联架构的延迟结构是串行的三段：ASR 出完整转写、LLM 出完整回复文本、TTS 出音频。每一段都要等前一段收敛，用户说完到听见回应之间存在多次进程/服务边界往返，且 LLM 必须等 ASR 给出终止判定才能起步。全双工多流方案把这三次往返压成一次前向内的交错注意力：</p>\n<div class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</div>\n<p>代价立刻体现在 KV 上：三路 KV 拼接后注意力模式不再是规则的因果三角，KV cache 需按流分区管理，显存占用近似为三路之和而非单路复用，带宽压力随交错顺序变化。具体例子：一个长会话中用户流持续增长，若未按流分区，用户侧 KV 会挤占助手侧预算，表现为长会话下显存溢出或助手流响应延迟抬升——这正是本方案最典型的失败模式。判据是：当 SLO 以端到端响应延迟与打断响应时间为衡量、且会话时长可控（可通过分段重置用户流缓解增长）时，并行度轴的收益成立；当部署环境只能承受单路 KV 的显存与带宽开销、或对话以严格轮次为主且打断稀少时，级联的串行结构反而更省。</p>\n<p>注意并行度并不免费：全双工训练数据稀缺，重叠语音与打断的鲁棒性依赖专门数据增强，数据不足时助手流会误触发或漏触发，轮次混乱。因此并行度轴的选型必须同时问一句“有没有重叠语音样本”，没有就退回单向流式 TTS 加外部 VAD 打断的折中形态。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-48\">四十八 · 对齐载体轴：内部文本 token 与外部文本接口</h3>\n<p>全双工方案用文本 token 作为用户流与助手流之间的内部桥梁，语音与文本语义在同一模型内保持一致，文本 token 可同步输出字幕，可控生成（如按文本约束语气、按字幕对齐）因此变得直接。级联方案的对齐发生在服务边界上：ASR 文本进、LLM 文本出、TTS 消费文本，语义一致性由三次独立模型各自保证，任何一段的偏差都会在下一段被放大且不可追溯。单向流式 TTS 则完全没有用户侧对齐载体，只能靠外挂 VAD 判断起止。</p>\n<p>工程代价分两侧。内部对齐让单次前向的序列变长（文本 token 夹在音频 token 之间），注意力计算量与 KV 占用上升，量化上以 FP16 为主、KV 按流分区；外部接口则把对齐成本转成多次序列化与跨服务传输，吞吐受进程边界限制但单模型显存压力小。具体例子：需要同步字幕的客服场景，内部对齐只需在助手流解码时旁路取出文本 token，而级联方案要额外维护 ASR 与 LLM 两套时间戳对齐逻辑，字幕与语音的偏移需另做后处理。判据是：字幕同步、语义可控、语音文本一致性属于硬需求时选内部对齐；若文本环节本就由独立可替换的 LLM 承担、且团队按服务边界划分职责，外部接口的运维边界更清晰。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-49\">四十九 · 状态可重置性轴：打断语义决定调度形态</h3>\n<p>打断不是附加功能，而是调度契约。全双工方案的打断路径是：打断检测触发助手流清空与 KV 重置，保留用户流状态继续监听。这要求 KV 按流分区，重置只作用于助手侧，用户侧编码状态与已积累的语义 token 不被丢弃。级联方案没有“保留用户流”的概念，打断等价于终止当前 TTS 并重启 ASR，用户已说出的部分要么重传要么丢失。单向流式 TTS 只能停播，无法在同一会话内继续监听。</p>\n<p>调度上的代价很具体：全双工部署需同时维持用户流编码与助手流解码两条流水，声码器流式解码与 LM 解码再做一层流水，SM 占用被切成多份，并发会话数受 SM 与显存双重限制。打断检测阈值设置不当会让重置滞后，用户打断后仍输出旧回应，交互出现明显错位——这是比显存溢出更难诊断的失败模式，因为它在指标上表现为“延迟正常但语义错位”。判据是：交互形态以可打断、重叠说话为常态（如实时助手、陪伴式对话）时，状态可重置性轴的收益压倒显存代价；若交互是严格的按键说话或单轮问答，重置语义用不上，级联的简单重启更稳。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>全双工多流 Transformer</th><th>级联 ASR/LLM/TTS</th><th>单向流式 TTS</th></tr></thead><tbody><tr><td>用户流与助手流并行</td><td>同模型交错注意力</td><td>串行三段</td><td>仅助手流</td></tr><tr><td>对齐载体</td><td>内部文本 token</td><td>外部文本接口</td><td>无用户侧载体</td></tr><tr><td>打断时状态处理</td><td>清助手 KV、留用户流</td><td>整链重启</td><td>停播</td></tr><tr><td>KV/显存开销</td><td>三路 KV 分区，最高</td><td>单模型分段，中等</td><td>单路，最低</td></tr><tr><td>主要失败模式</td><td>KV 未分区致长会话溢出、打断阈值滞后</td><td>多次往返延迟、语义偏差累积</td><td>无法打断、轮次僵硬</td></tr><tr><td>适用条件</td><td>低延迟可打断、有重叠语音数据增强</td><td>轮次清晰、服务边界可替换</td><td>播报型、无打断需求</td></tr></tbody></table>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-50\">五十 · 决策表落地：按 SLO 与预算反推，而非按模型名气</h3>\n<p>把三条轴压成可执行的选型顺序：先定 SLO 里是否含“打断响应时间”这一项。含，则状态可重置性轴为硬约束，候选集只剩全双工多流方案；不含，再看端到端响应延迟是否被多次往返卡住，若是则考虑全双工或至少单向流式 TTS 加流式 LLM 的折中；若延迟可接受且文本环节需独立替换，级联仍是运维上最省心的形态。第二步查数据：全双工路径必须有重叠语音与打断的专门数据增强，缺此项则不应选它，因为鲁棒性不足会让轮次混乱，其代价高于延迟收益。第三步查预算：双流交错使 KV cache 与注意力模式复杂、显存与带宽开销高，并发会话数受 SM 与显存限制，容量规划须按三路 KV 之和而非单路估算，量化以 FP16 为主并按流分区。</p>\n<p>一个具体的反推例子：若目标形态是实时语音助手，SLO 同时约束端到端响应延迟与打断响应时间，且团队已具备重叠语音增强数据，则选全双工多流方案，并在部署上强制 KV 按流分区、打断检测走独立轻量路径以免滞后；若同一团队的数据只有干净单说话人样本，则应选单向流式 TTS 配合外部 VAD 打断，把“可打断”降级为“可停播”，用显存与带宽的节省换取鲁棒性。决策表的价值在于它把“选哪个模型”变成“先确认哪条轴是硬约束”，从而避免在没有重叠语音数据时硬上全双工、在需要字幕同步时退回级联这类错配。</p>\n<p>最后一条工程判断：三条轴中，状态可重置性最难事后补——KV 未按流分区是架构级决定，改造成本高于换模型；并行度与对齐载体则可通过服务编排在级联与全双工之间做灰度。因此选型时应优先锁定打断语义与 KV 分区方案，再在剩余预算内决定并行度与对齐载体，而不是反过来先挑模型再补调度。</p>\n\n<h3 id=\"alg-dual-stream-full-duplex-sec-51\">五十一 · 边界判定：三族语音对话推理的选型分水岭</h3>\n<p>把双流全双工放进同族算法谱系里，它只在“用户说话时助手必须同时出声”这一条硬约束下不可替代。级联 ASR→LLM→TTS 的代价结构是串行三段往返，其轮次延迟近似 <span class=\"formula\">$$L_{\\text{turn}} = t_{\\text{enc}}(B_u) + t_{\\text{lm}}(B_a) + t_{\\text{voc}}(B_a)$$</span>，三段各自排队、各自首块延迟叠加，且结构上不存在“边听边说”的状态；单向流式 TTS 把 LM 与声码器流水化，压掉了段间往返，但输入侧仍是回合制，用户流不参与并行建模。双流方案的增量价值全部押在打断与重叠语音上：它用 <span class=\"formula\">$$h_t^{\\text{asst}}=\\mathrm{Attn}\\big(q_t^{\\text{asst}},\\,[K^{\\text{user}}\\oplus K^{\\text{asst}}\\oplus K^{\\text{text}}],\\,[V^{\\text{user}}\\oplus V^{\\text{asst}}\\oplus V^{\\text{text}}]\\big)$$</span> 把用户流 KV 常驻在助手流每一步的注意力窗口里，代价是注意力模式从单流因果变成三源交错，KV 必须按流分区管理。选型的第一道分水岭因此不是模型能力，而是产品是否真的需要亚秒级打断响应——不需要，级联或单向流式的显存与调度复杂度低一个档位，工程风险小得多。</p>\n<p>第二道分水岭是并发会话数与显存预算。双流交错下每条会话持有用户流、助手流、文本 token 三份 KV，批大小直接受双流 KV 显存约束，并发上限受 SM 与显存共同限制；用户流持续增长而助手流按块推进，若 KV 未按流分区，长会话里用户流会挤占助手流显存，表现为显存溢出或响应延迟爬升。这是双流方案最典型的失效路径，也是它与单向流式 TTS 在容量规划上的本质差异：后者的 KV 随输出长度单调增长、可预估，前者是两条不同增长速率的流共享一个池。部署时量化以 FP16 为主，声码器流式解码与 LM 解码做流水，用户流编码与助手流解码并行占用不同 SM 分区，这些都需要在调度器里显式表达，而不能指望框架默认行为。</p>\n<p>第三道分水岭是数据与鲁棒性。全双工训练数据稀缺，重叠语音与打断样本不足时，打断检测阈值稍偏就会两头出错：阈值迟钝则助手流清空与 KV 重置滞后，用户打断后仍吐旧回应，交互错位肉眼可见；阈值过敏则助手流误触发清空，对话轮次混乱。这类失败不体现在单条请求的延迟指标上，而体现在会话级 SLO 的打断响应时间分布尾部。因此选型判断应写成条件式：需要自然打断且能持续供给重叠语音增强数据，选双流；只需低首包延迟、交互允许回合制，选单向流式 TTS；只需把现有文本栈语音化、对延迟不敏感，选级联。三者不是精度高低之分，而是状态机复杂度与数据成本的交换。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>并行听说的能力</th><th>主要系统代价</th><th>适用条件</th></tr></thead><tbody><tr><td>级联 ASR/LLM/TTS</td><td>无，回合制</td><td>三段串行往返，首包延迟叠加</td><td>文本栈复用、延迟容忍</td></tr><tr><td>单向流式 TTS</td><td>输出侧流式，输入侧回合制</td><td>KV 随输出单调增长，可预估</td><td>低首包延迟、无需打断</td></tr><tr><td>双流全双工</td><td>用户流与助手流交错并行</td><td>三源 KV 分区、显存与带宽开销高</td><td>可打断交互且有重叠语音数据</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 流式编解码器与首包延迟</td></tr><tr><td>解决什么</td><td>传统语音对话先 ASR 再 LLM 再 TTS 的级联架构延迟高，且无法在用户说话时同时生成回应，交互不自然。</td></tr><tr><td>一句话机制</td><td>用单一多流 Transformer 同时建模用户音频流与助手音频流，以文本 token 为内部对齐，实现听与说并行的全…</td></tr><tr><td>代价与失效</td><td>双流交错使 KV cache 与注意力模式复杂，显存与带宽开销高；全双工训练数据稀缺，打断与重叠语音的鲁棒性需专门数据增强</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-dual-stream-full-duplex · 共 8 个片段</p>\n";break;}}})();
